<?php
declare(strict_types=1);
namespace EnglAI\Learning;
final class ReadingSessionService
{
 public const QUESTIONS=20,TIMER=20;
 public function __construct(private readonly \PDO $pdo){}
 public static function canonicalLevel(string$level):string{$value=strtolower(trim($level));return match($value){'basic','beginner'=>'basic','intermediate'=>'intermediate','advanced'=>'advanced',default=>throw new \InvalidArgumentException('Level Reading tidak valid.')};}
 public function productionLevelAvailability(int$classroomId,int$memberId):array
 {
  $plan=$this->pdo->prepare('SELECT id FROM classroom_lesson_plans WHERE classroom_id=? AND is_active=1 ORDER BY version DESC LIMIT 1');$plan->execute([$classroomId]);$planId=(int)$plan->fetchColumn();if(!$planId)return[];
  $provided=$this->pdo->prepare("SELECT level FROM learning_modules WHERE classroom_id=? AND lesson_plan_id=? AND skill='reading' AND status='ready'");$provided->execute([$classroomId,$planId]);$enabled=[];foreach($provided->fetchAll(\PDO::FETCH_COLUMN)as$raw){try{$enabled[self::canonicalLevel((string)$raw)]=true;}catch(\InvalidArgumentException){}}
  $result=[];foreach(['basic','intermediate','advanced']as$level){if(!isset($enabled[$level]))continue;$q=$this->pdo->prepare("SELECT content_json,source,status FROM learning_activities WHERE classroom_id=? AND lesson_plan_id=? AND skill='reading' AND level=? AND activity_type='standalone_question'");$q->execute([$classroomId,$planId,$level]);$ids=[];$texts=[];$gemini=0;$fallback=0;$archived=0;$latest=null;foreach($q->fetchAll()as$row){$item=json_decode((string)$row['content_json'],true)?:[];$isGemini=$row['source']==='ai'&&($item['source']??'')==='gemini';if(!$isGemini){$fallback++;if($row['status']!=='ready')$archived++;continue;}if($row['status']!=='ready'){$archived++;continue;}$id=(string)($item['id']??'');$text=self::normalizeQuestionText((string)($item['question']??''));$options=array_column($item['options']??[],'id');if($id===''||$text===''||isset($ids[$id])||isset($texts[$text])||count($options)!==4||count(array_unique($options))!==4||!in_array($item['correct_option_id']??'',$options,true))continue;$ids[$id]=true;$texts[$text]=true;$gemini++;$generated=(string)($item['generated_at']??'');if($generated!==''&&($latest===null||$generated>$latest))$latest=$generated;}
   $active=$this->pdo->prepare("SELECT id,current_position,score,snapshot_json FROM reading_sessions WHERE classroom_id=? AND member_id=? AND lesson_plan_id=? AND level=? AND status='active' ORDER BY id DESC LIMIT 1");$active->execute([$classroomId,$memberId,$planId,$level]);$session=$active->fetch()?:null;if($session){$snap=json_decode((string)$session['snapshot_json'],true)?:[];foreach($snap['questions']??[]as$item)if(($item['source']??'')!=='gemini'){$session=null;break;}}
   $completed=$this->pdo->prepare("SELECT COUNT(*) FROM reading_sessions WHERE classroom_id=? AND member_id=? AND lesson_plan_id=? AND level=? AND status='completed' AND current_position=20");$completed->execute([$classroomId,$memberId,$planId,$level]);$completedCount=(int)$completed->fetchColumn();$ready=$gemini>=20;$status=!$ready?'preparing':($session?'in_progress':($completedCount>0?'completed':'available'));$result[$level]=['level'=>$level,'provided'=>true,'ready'=>$ready,'status'=>$status,'valid_count'=>$gemini,'gemini_count'=>$gemini,'fallback_count'=>$fallback,'archived_count'=>$archived,'low_stock'=>$gemini<40,'last_generated_at'=>$latest,'active_session'=>$session,'completed_sessions'=>$completedCount];if(!$ready)app_log('warning','Gemini Reading level preparing',['classroom_id'=>$classroomId,'lesson_plan_id'=>$planId,'level'=>$level,'gemini_valid'=>$gemini,'fallback_excluded'=>$fallback]);}
  return$result;
 }
 public function levelAvailability(int$classroomId,int$memberId):array{$plan=$this->pdo->prepare('SELECT id FROM classroom_lesson_plans WHERE classroom_id=? AND is_active=1 ORDER BY version DESC LIMIT 1');$plan->execute([$classroomId]);$planId=(int)$plan->fetchColumn();if(!$planId)return[];$provided=$this->pdo->prepare("SELECT level FROM learning_modules WHERE classroom_id=? AND lesson_plan_id=? AND skill='reading' AND status='ready' UNION SELECT level FROM learning_activities WHERE classroom_id=? AND lesson_plan_id=? AND skill='reading' AND status='ready'");$provided->execute([$classroomId,$planId,$classroomId,$planId]);$levels=[];foreach($provided->fetchAll(\PDO::FETCH_COLUMN)as$raw){try{$levels[self::canonicalLevel((string)$raw)]=true;}catch(\InvalidArgumentException){}}$result=[];foreach(['basic','intermediate','advanced']as$level){if(!isset($levels[$level]))continue;$q=$this->pdo->prepare("SELECT content_json,source FROM learning_activities WHERE classroom_id=? AND lesson_plan_id=? AND skill='reading' AND level=? AND activity_type='standalone_question' AND status='ready'");$q->execute([$classroomId,$planId,$level]);$ids=[];$texts=[];$valid=0;$sources=['gemini'=>0,'local_fallback'=>0];$total=0;foreach($q->fetchAll()as$row){$total++;$item=json_decode((string)$row['content_json'],true);$id=(string)($item['id']??'');$text=self::normalizeQuestionText((string)($item['question']??''));$options=array_column($item['options']??[],'id');if($id===''||$text===''||isset($ids[$id])||isset($texts[$text])||count($options)!==4||count(array_unique($options))!==4||!in_array($item['correct_option_id']??'',$options,true))continue;$ids[$id]=true;$texts[$text]=true;$valid++;$source=(string)($item['source']??($row['source']==='ai'?'gemini':'local_fallback'));if(isset($sources[$source]))$sources[$source]++;}$active=$this->pdo->prepare("SELECT id,current_position,score FROM reading_sessions WHERE classroom_id=? AND member_id=? AND lesson_plan_id=? AND level=? AND status='active' ORDER BY id DESC LIMIT 1");$active->execute([$classroomId,$memberId,$planId,$level]);$session=$active->fetch()?:null;$completed=$this->pdo->prepare("SELECT COUNT(*) FROM reading_sessions WHERE classroom_id=? AND member_id=? AND lesson_plan_id=? AND level=? AND status='completed' AND current_position=20");$completed->execute([$classroomId,$memberId,$planId,$level]);$completedCount=(int)$completed->fetchColumn();$status=$session?'in_progress':($completedCount>0?'completed':($valid>=20?'available':'preparing'));$result[$level]=['level'=>$level,'provided'=>true,'ready'=>$valid>=20,'status'=>$status,'total_records'=>$total,'valid_count'=>$valid,'unique_ids'=>count($ids),'unique_texts'=>count($texts),'sources'=>$sources,'active_session'=>$session,'completed_sessions'=>$completedCount];if($valid<20)app_log('warning','Reading level bank not ready',['classroom_id'=>$classroomId,'lesson_plan_id'=>$planId,'level'=>$level,'total_standalone'=>$total,'valid'=>$valid,'unique_ids'=>count($ids),'unique_texts'=>count($texts),'sources'=>$sources]);}return$result;}
 public function start(int $classroomId,int $memberId,string $level,bool $forceNew=false):int
 {
  $level=self::canonicalLevel($level);if(!$forceNew){$q=$this->pdo->prepare("SELECT id,snapshot_json FROM reading_sessions WHERE classroom_id=? AND member_id=? AND level=? AND status='active' ORDER BY id DESC LIMIT 1");$q->execute([$classroomId,$memberId,$level]);if($row=$q->fetch()){try{$snapshot=json_decode((string)$row['snapshot_json'],true)?:[];self::assertSnapshot($snapshot);self::assertGeminiSnapshot($snapshot);return(int)$row['id'];}catch(\RuntimeException){$this->pdo->prepare("UPDATE reading_sessions SET status='completed',completed_at=NOW() WHERE id=?")->execute([(int)$row['id']]);}}}
  $q=$this->pdo->prepare('SELECT id FROM classroom_lesson_plans WHERE classroom_id=? AND is_active=1 ORDER BY version DESC LIMIT 1');$q->execute([$classroomId]);$planId=(int)$q->fetchColumn();if(!$planId)throw new \RuntimeException('Reading content sedang dipersiapkan.');
  $q=$this->pdo->prepare("SELECT l.*,MAX(CASE WHEN rs.member_id=? THEN ra.answered_at END) last_used FROM learning_activities l LEFT JOIN reading_attempts ra ON ra.passage_id=l.id LEFT JOIN reading_sessions rs ON rs.id=ra.reading_session_id WHERE l.classroom_id=? AND l.lesson_plan_id=? AND l.skill='reading' AND l.level=? AND l.activity_type='standalone_question' AND l.source='ai' AND l.status='ready' GROUP BY l.id ORDER BY last_used IS NULL DESC,last_used ASC,RAND()");$q->execute([$memberId,$classroomId,$planId,$level]);$pool=[];$ids=[];$texts=[];$contexts=[];foreach($q->fetchAll()as$row){$item=json_decode((string)$row['content_json'],true);if(!is_array($item)||($item['source']??'')!=='gemini')continue;$id=(string)($item['id']??'');$text=self::normalizeQuestionText((string)($item['question']??''));$context=self::normalizeQuestionText((string)($item['short_context']??''));$optionIds=array_column($item['options']??[],'id');if($id===''||$text===''||isset($ids[$id])||isset($texts[$text])||($context!==''&&isset($contexts[$context]))||count($optionIds)!==4||count(array_unique($optionIds))!==4||!in_array($item['correct_option_id']??'',$optionIds,true))continue;$item['activity_id']=(int)$row['id'];$pool[]=$item;$ids[$id]=true;$texts[$text]=true;if($context!=='')$contexts[$context]=true;if(count($pool)===20)break;}if(count($pool)<20)throw new \RuntimeException('Reading content is being prepared by your Teacher.');
  $pool=array_values(array_filter($pool,static fn(array$item):bool=>($item['source']??'')==='gemini'));if(count($pool)<20)throw new \RuntimeException('Reading content is being prepared by your Teacher.');$pool=array_slice($pool,0,20);shuffle($pool);$positions=self::balancedPositions();foreach($pool as$i=>&$item){$correct=(string)$item['correct_option_id'];$right=null;$others=[];foreach($item['options']as$option){if((string)$option['id']===$correct)$right=$option;else$others[]=$option;}shuffle($others);array_splice($others,$positions[$i],0,[$right]);$item['options']=array_values($others);}unset($item);$snapshot=['questions'=>$pool];self::assertSnapshot($snapshot);self::assertGeminiSnapshot($snapshot);
  $q=$this->pdo->prepare("INSERT INTO reading_sessions(classroom_id,member_id,lesson_plan_id,level,total_questions,current_position,score,snapshot_json,status,started_at) VALUES(?,?,?,?,20,0,0,?,'active',NOW())");$q->execute([$classroomId,$memberId,$planId,$level,json_encode($snapshot,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);return(int)$this->pdo->lastInsertId();
 }
 public function get(int$id,int$memberId,bool$lock=false):array{$q=$this->pdo->prepare('SELECT * FROM reading_sessions WHERE id=? AND member_id=?'.($lock?' FOR UPDATE':''));$q->execute([$id,$memberId]);$s=$q->fetch();if(!$s)throw new \RuntimeException('Reading session tidak ditemukan.');$s['snapshot']=json_decode((string)$s['snapshot_json'],true)?:[];return$s;}
 public function question(array$s):?array{$position=(int)$s['current_position'];return$position>=20?null:($s['snapshot']['questions'][$position]??null);}
 public function publicState(array$s):array{$q=$this->question($s);if(!$q)return['completed'=>true,'current_index'=>(int)$s['current_position'],'score'=>(int)$s['score']];unset($q['correct_option_id'],$q['explanation'],$q['fingerprint']);return['completed'=>false,'current_index'=>(int)$s['current_position'],'score'=>(int)$s['score'],'question'=>$q];}
 public function beginQuestion(int$id,int$memberId):void{$this->pdo->prepare("UPDATE reading_sessions SET question_started_at=COALESCE(question_started_at,NOW()) WHERE id=? AND member_id=? AND status='active'")->execute([$id,$memberId]);}
 public function answer(int$id,int$memberId,string$questionId,?string$selected,bool$clientTimeout):array{$this->pdo->beginTransaction();try{$s=$this->get($id,$memberId,true);$check=$this->pdo->prepare('SELECT * FROM reading_attempts WHERE reading_session_id=? AND question_id=?');$check->execute([$id,$questionId]);if($attempt=$check->fetch()){$this->pdo->commit();$fresh=$this->get($id,$memberId);return$this->response($attempt,$s,$fresh,true);}$q=$this->question($s);if($s['status']!=='active')throw new \RuntimeException('SESSION_COMPLETED');if(!$q||!hash_equals((string)$q['id'],$questionId))throw new \RuntimeException('STALE_QUESTION');$elapsed=$s['question_started_at']?max(0,(time()-strtotime((string)$s['question_started_at']))*1000):0;$timed=$clientTimeout||$elapsed>self::TIMER*1000;$options=array_map('strval',array_column($q['options'],'id'));if(!$timed&&($selected===null||!in_array($selected,$options,true)))throw new \InvalidArgumentException('INVALID_OPTION');$correct=!$timed&&hash_equals((string)$q['correct_option_id'],(string)$selected);$result=$timed?'timed_out':($correct?'correct':'incorrect');$points=$correct?5:0;$insert=$this->pdo->prepare('INSERT INTO reading_attempts(reading_session_id,passage_id,question_id,option_order_json,selected_option_id,result,response_ms,score,answered_at) VALUES(?,?,?,?,?,?,?,?,NOW())');$insert->execute([$id,$q['activity_id'],$q['id'],json_encode($options),$selected,$result,$elapsed,$points]);$attempt=['question_id'=>$q['id'],'selected_option_id'=>$selected,'result'=>$result,'score'=>$points];$next=(int)$s['current_position']+1;$done=$next>=20;$update=$this->pdo->prepare("UPDATE reading_sessions SET current_position=?,score=score+?,question_started_at=NULL,status=?,completed_at=IF(?='completed',NOW(),NULL) WHERE id=? AND member_id=?");$update->execute([$next,$points,$done?'completed':'active',$done?'completed':'active',$id,$memberId]);$this->pdo->commit();return$this->response($attempt,$s,$this->get($id,$memberId),false);}catch(\Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}}
 private function response(array$attempt,array$answeredSession,array$fresh,bool$duplicate):array{$q=$this->find($answeredSession,(string)$attempt['question_id']);$correctId=(string)$q['correct_option_id'];$correctText='';foreach($q['options']as$option)if((string)$option['id']===$correctId){$correctText=(string)$option['text'];break;}return['success'=>true,'correct'=>$attempt['result']==='correct','result'=>$attempt['result'],'selected_option_id'=>$attempt['selected_option_id'],'correct_option_id'=>$correctId,'correct_option_text'=>$correctText,'explanation'=>(string)$q['explanation'],'score'=>(int)$fresh['score'],'current_index'=>(int)$fresh['current_position'],'answered_count'=>(int)$fresh['current_position'],'completed'=>$fresh['status']==='completed','duplicate'=>$duplicate,'next_state'=>$this->publicState($fresh)];}
 private function find(array$s,string$id):array{foreach(($s['snapshot']['questions']??[])as$q)if(hash_equals((string)($q['id']??''),$id))return$q;throw new \RuntimeException('STALE_QUESTION');}
 public function attempts(int$id):array{$q=$this->pdo->prepare('SELECT * FROM reading_attempts WHERE reading_session_id=? ORDER BY id');$q->execute([$id]);return$q->fetchAll();}
 public static function normalizeQuestionText(string$text):string{return mb_strtolower(trim(preg_replace('/\s+/u',' ',preg_replace('/[^\pL\pN\s]/u',' ',$text)??$text)??$text));}
 public static function assertSnapshot(array$snapshot):void{$questions=$snapshot['questions']??[];if(!is_array($questions)||count($questions)!==20)throw new \RuntimeException('Reading session harus berisi 20 standalone questions.');$ids=[];$texts=[];$contexts=[];foreach($questions as$q){$id=(string)($q['id']??'');$text=self::normalizeQuestionText((string)($q['question']??''));$context=self::normalizeQuestionText((string)($q['short_context']??''));if($id===''||$text===''||isset($ids[$id])||isset($texts[$text])||($context!==''&&isset($contexts[$context])))throw new \RuntimeException('Reading snapshot harus memiliki 20 pertanyaan dan konteks unik.');$ids[$id]=true;$texts[$text]=true;if($context!=='')$contexts[$context]=true;}}
 public static function assertGeminiSnapshot(array $snapshot):void{foreach($snapshot['questions']??[]as$q)if(($q['source']??'')!=='gemini')throw new \RuntimeException('Reading production session hanya boleh memakai bank Gemini.');}
 public static function balancedPositions():array{do{$v=array_merge(array_fill(0,5,0),array_fill(0,5,1),array_fill(0,5,2),array_fill(0,5,3));shuffle($v);$ok=true;for($i=2;$i<20;$i++)if($v[$i]===$v[$i-1]&&$v[$i]===$v[$i-2]){$ok=false;break;}}while(!$ok);return$v;}
}
